-- Hillsbrad Foothills: creature abilities
-- Most of the zone's creatures (the Forsaken and Stormpike of the front, the Hillsbrad humans, SI:7 agents, Syndicate, ogres,
-- spiders and wildlife) had no AI or ran classic rows. Hillsbrad is the Cataclysm revamp, so port their abilities from the Cataclysm
-- data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place. The Hill Fawn does not bless
-- itself, which would set off its quest. The creatures no reference scripts (Stormpike Trainees, wild spiders, guards) cast their
-- sniffed spells (creature_template spell1-8).

SET @ENTRIES := '2269,2270,2319,2344,2356,2358,2369,2371,2373,2376,2385,2386,2416,2628,13219,14221,14277,14278,14280,45728,45734,47010,47204,47214,47484,47759,47786,47789,47790,47792,47793,47859,47861,47871,48080,48083,48136,48158,48184,48187,48260,48268,48269,48272,48319,48322,48482,48483,48484,48628,48741,48742,48878,48880,48922,48923,48924,49116,49245,49249,49263,49264,49265,49266,49268,49269,49348,49349';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '14881,48912,51842,51843,51916';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
